use "./sim.ts" { createBalls, step, draw }

page Sim "/" {
  ref box
  ref balls
  ref raf
  ref running
  state count = 5
  state frames = 0
  state paused = false

  fn loop() {
    if !running { return }
    step(balls, 400, 300)
    draw(box, balls)
    frames++
    raf = requestAnimationFrame(loop)
  }

  fn add() {
    balls.push(...createBalls(1, 400, 300))
    count = balls.length
    draw(box, balls)
  }

  fn togglePause() {
    if paused {
      paused = false
      running = true
      raf = requestAnimationFrame(loop)
    } else {
      paused = true
      running = false
      cancelAnimationFrame(raf)
    }
  }

  fn reset() {
    balls = createBalls(5, 400, 300)
    count = 5
    frames = 0
    draw(box, balls)
  }

  mount {
    balls = createBalls(5, 400, 300)
    draw(box, balls)
    running = true
    raf = requestAnimationFrame(loop)
    cleanup {
      running = false
      cancelAnimationFrame(raf)
    }
  }

  column gap=3 pad=4 {
    title "Simulación de pelotas"
    canvas ref=box id="sim" width=400 height=300 style="border:1px solid #888"
    row gap=2 {
      button "Agregar" primary -> add()
      button (paused ? "Reanudar" : "Pausar") -> togglePause()
      button "Reiniciar" danger -> reset()
    }
    text `Pelotas: ${count}`
    text `Cuadros: ${frames}`
  }
}

