export function createBalls(n: number, w: number, h: number) {
  const r = 10;
  const out: any[] = [];
  for (let i = 0; i < n; i++) {
    out.push({
      x: r + Math.random() * (w - 2 * r),
      y: r + Math.random() * (h - 2 * r),
      vx: (Math.random() - 0.5) * 6,
      vy: (Math.random() - 0.5) * 6,
      r,
    });
  }
  return out;
}

export function step(balls: any[], w: number, h: number) {
  for (const b of balls) {
    b.vy += 0.2;
    b.x += b.vx;
    b.y += b.vy;
    if (b.x < b.r) { b.x = b.r; b.vx = Math.abs(b.vx); }
    if (b.x > w - b.r) { b.x = w - b.r; b.vx = -Math.abs(b.vx); }
    if (b.y < b.r) { b.y = b.r; b.vy = Math.abs(b.vy); }
    if (b.y > h - b.r) { b.y = h - b.r; b.vy = -Math.abs(b.vy); }
  }
  for (let i = 0; i < balls.length; i++) {
    for (let j = i + 1; j < balls.length; j++) {
      const a = balls[i], b = balls[j];
      const dx = b.x - a.x, dy = b.y - a.y;
      const min = a.r + b.r;
      const d2 = dx * dx + dy * dy;
      if (d2 < min * min) {
        const d = Math.sqrt(d2) || 0.001;
        const nx = dx / d, ny = dy / d;
        const overlap = (min - d) / 2;
        a.x -= nx * overlap; a.y -= ny * overlap;
        b.x += nx * overlap; b.y += ny * overlap;
        let t = a.vx; a.vx = b.vx; b.vx = t;
        t = a.vy; a.vy = b.vy; b.vy = t;
        for (const p of [a, b]) {
          p.x = Math.min(w - p.r, Math.max(p.r, p.x));
          p.y = Math.min(h - p.r, Math.max(p.r, p.y));
        }
      }
    }
  }
}

export function draw(canvas: HTMLCanvasElement, balls: any[]) {
  const ctx = canvas.getContext("2d")!;
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  ctx.fillStyle = "#e11d48";
  for (const b of balls) {
    ctx.beginPath();
    ctx.arc(b.x, b.y, b.r, 0, Math.PI * 2);
    ctx.fill();
  }
}

